-- ============================================================================
-- Sample Schema & Fixture Data for Power BI / BI-02 Early Development (BI-01)
-- Conforms strictly to Gold schema generated by GoldEventTransformer & GoldPublisher.
-- Dialect: ANSI SQL / SQLite compatible for local standalone development.
-- ============================================================================

-- 1. Fact Table: event_current (Gold Canonical Events)
DROP TABLE IF EXISTS event_current;
CREATE TABLE event_current (
    schema_version TEXT NOT NULL,
    canonical_event_id TEXT PRIMARY KEY,
    primary_observation_id TEXT NOT NULL,
    canonical_source_system TEXT NOT NULL,
    event_time_utc TEXT NOT NULL,
    event_time_jst TEXT NOT NULL,
    event_date_utc TEXT NOT NULL,
    event_date_jst TEXT NOT NULL,
    event_date_key_utc INTEGER NOT NULL,
    event_date_key_jst INTEGER NOT NULL,
    latitude REAL NOT NULL,
    longitude REAL NOT NULL,
    depth_km REAL,
    magnitude REAL,
    magnitude_type TEXT,
    event_type_code TEXT NOT NULL,
    is_natural_earthquake INTEGER NOT NULL,
    place_name TEXT,
    is_in_study_area INTEGER NOT NULL,
    region_key TEXT NOT NULL,
    region_name TEXT NOT NULL,
    region_category TEXT NOT NULL,
    magnitude_band_code TEXT NOT NULL,
    depth_band_code TEXT NOT NULL,
    tsunami_flag INTEGER,
    alert_level TEXT,
    significance INTEGER,
    max_intensity_code TEXT,
    determining_agency_code TEXT,
    catalog_era TEXT,
    source_count INTEGER NOT NULL,
    has_usgs INTEGER NOT NULL,
    has_jma INTEGER NOT NULL,
    source_coverage_code TEXT NOT NULL,
    link_status TEXT NOT NULL,
    quality_status TEXT NOT NULL,
    canonical_model_version TEXT NOT NULL,
    gold_run_id TEXT NOT NULL,
    record_updated_at_utc TEXT NOT NULL
);

-- 2. Publication Gate Status Table
DROP TABLE IF EXISTS publication_status;
CREATE TABLE publication_status (
    publication_id TEXT PRIMARY KEY,
    gold_run_id TEXT NOT NULL,
    snapshot_id INTEGER NOT NULL,
    gold_table_name TEXT NOT NULL,
    physical_gold_table_name TEXT NOT NULL,
    committed_at_utc TEXT NOT NULL,
    verified_at_utc TEXT NOT NULL,
    published_at_utc TEXT NOT NULL,
    max_event_time_utc TEXT NOT NULL,
    event_count INTEGER NOT NULL,
    schema_version TEXT NOT NULL,
    verify_status TEXT NOT NULL,
    bundle_sha256 TEXT NOT NULL,
    snapshot_bundle_json TEXT,
    scope_json TEXT,
    serving_view TEXT NOT NULL
);

-- 3. Dimension Tables
DROP TABLE IF EXISTS dim_date;
CREATE TABLE dim_date (
    date_key INTEGER PRIMARY KEY,
    calendar_date TEXT NOT NULL,
    year INTEGER NOT NULL,
    quarter INTEGER NOT NULL,
    month INTEGER NOT NULL,
    month_name TEXT NOT NULL,
    day_of_month INTEGER NOT NULL,
    day_of_week INTEGER NOT NULL,
    is_weekend INTEGER NOT NULL
);

DROP TABLE IF EXISTS dim_region;
CREATE TABLE dim_region (
    region_key TEXT PRIMARY KEY,
    region_name TEXT NOT NULL,
    region_category TEXT NOT NULL
);

DROP TABLE IF EXISTS dim_magnitude_band;
CREATE TABLE dim_magnitude_band (
    band_code TEXT PRIMARY KEY,
    band_label TEXT NOT NULL,
    sort_order INTEGER NOT NULL
);

DROP TABLE IF EXISTS dim_depth_band;
CREATE TABLE dim_depth_band (
    band_code TEXT PRIMARY KEY,
    band_label TEXT NOT NULL,
    sort_order INTEGER NOT NULL
);

